def split_rows(raw):
	if isinstance(raw, str):
		try:
			raw = json.loads(raw)
		except Exception:
			raw = [raw]
	out = []
	for item in raw or []:
		parts = []
		for part in str(item).split("|"):
			parts.append(part.strip())
		if parts and parts[0]:
			out.append(parts)
	return out


def num(value):
	try:
		text = str(value).replace(",", "").replace("$", "").replace("%", "").strip()
		if not text:
			return None
		return float(text)
	except Exception:
		return None


def money(value, cur):
	digits = str(int(round(value)))
	out = ""
	while len(digits) > 3:
		out = "," + digits[-3:] + out
		digits = digits[:-3]
	return cur + digits + out


def slugify(text):
	out = ""
	for ch in str(text or "").lower():
		out = out + (ch if ch.isalnum() else "-")
	return out


def fixed(value):
	return str(round(value, 2))

def axis_ticks(lo, hi):
	if lo is None or lo <= 0:
		lo = 1.0
	if hi is None or hi <= lo:
		hi = lo * 10
	ticks = [lo]
	power = 1.0
	while power * 10 <= lo:
		power = power * 10
	while power > lo:
		power = power / 10
	done = False
	guard = 0
	while not done and guard < 40:
		for mult in [1, 2.5, 5]:
			value = mult * power
			if value >= hi:
				done = True
				break
			if value > lo:
				ticks.append(value)
		power = power * 10
		guard = guard + 1
	ticks.append(hi)
	return ticks


def axis_pos(value, ticks):
	n = len(ticks)
	if n < 2 or value <= ticks[0]:
		return 0.0
	if value >= ticks[n - 1]:
		return 100.0
	i = 0
	while i < n - 2 and value > ticks[i + 1]:
		i = i + 1
	frac = (value - ticks[i]) / (ticks[i + 1] - ticks[i])
	return (i + frac) / (n - 1) * 100.0


def tick_label(value, cur):
	if value >= 1000000:
		x = value / 1000000.0
		suffix = "M"
	elif value >= 1000:
		x = value / 1000.0
		suffix = "K"
	else:
		x = value
		suffix = ""
	if x == int(x):
		shown = str(int(x))
	else:
		shown = str(round(x, 1))
	return cur + shown + suffix


def tape_ticks(ticks, cur, tick_label):
	out = []
	n = len(ticks)
	for i in range(n):
		x = 0.0 if n < 2 else i * 100.0 / (n - 1)
		edge = "mid"
		if i == 0:
			edge = "start"
		if i == n - 1:
			edge = "end"
		crowded = "true" if (n > 4 and (i == 1 or i == n - 2)) else "false"
		out.append({"x": str(round(x, 4)) + "%", "label": tick_label(ticks[i], cur), "major": "true", "edge": edge, "crowded": crowded})
		if i < n - 1:
			out.append({"x": str(round((i + 0.5) * 100.0 / (n - 1), 4)) + "%", "label": "", "major": "false", "edge": "mid", "crowded": "true"})
	return out


def axis_marks(ticks, cur, tick_label):
	out = []
	n = len(ticks)
	for i in range(n):
		edge = "mid"
		if i == 0:
			edge = "start"
		if i == n - 1:
			edge = "end"
		out.append({
			"x": str(round(0.0 if n < 2 else i * 100.0 / (n - 1), 4)) + "%",
			"label": tick_label(ticks[i], cur),
			"edge": edge,
			"crowded": "true" if (n > 4 and (i == 1 or i == n - 2)) else "false",
		})
	return out

cur = str(props.get("currency") or "$")
adds = str(props.get("adds_label") or "Adds")
ticks = axis_ticks(num(props.get("axis_min")), num(props.get("axis_max")))
jobs = []
for parts in split_rows(props.get("jobs")):
	if len(parts) < 3:
		continue
	low = num(parts[1])
	high = num(parts[2])
	if low is None or high is None:
		continue
	if high < low:
		swap = low
		low = high
		high = swap
	per = num(parts[3]) if len(parts) > 3 else 0
	first = len(jobs) == 0
	jobs.append({
		"name": parts[0],
		"low": low,
		"high": high,
		"per": per or 0,
		"slug": parts[4] if len(parts) > 4 else "",
		"val": money(low, cur) + " to " + money(high, cur),
		"value": str(len(jobs)),
		"checked": first,
		"unchecked": not first,
	})
extras = []
for parts in split_rows(props.get("extras")):
	add = num(parts[1]) if len(parts) > 1 else None
	if add is None:
		continue
	mode = "flat"
	if len(parts) > 2 and parts[2].lower().startswith("per"):
		mode = "percent"
	shown = adds + " " + money(add, cur)
	if mode == "percent":
		shown = adds + " " + str(int(add)) + "%"
	if len(parts) > 3 and parts[3]:
		shown = parts[3]
	extras.append({"label": parts[0], "add": add, "mode": mode, "val": shown, "value": str(len(extras))})
timings = []
for parts in split_rows(props.get("timings")):
	add = num(parts[1]) if len(parts) > 1 else 0
	if add is None:
		add = 0
	shown = adds + " " + money(add, cur)
	if len(parts) > 2 and parts[2]:
		shown = parts[2]
	first = len(timings) == 0
	timings.append({"label": parts[0], "add": add, "val": shown, "value": str(int(round(add))), "checked": first, "unchecked": not first})
others = []
for parts in split_rows(props.get("other_jobs")):
	if len(parts) > 1:
		others.append({"slug": parts[0], "text": parts[1]})
low = 0
high = 0
words = ""
if jobs:
	low = jobs[0]["low"]
	high = jobs[0]["high"]
	words = jobs[0]["name"]
if timings:
	low = low + timings[0]["add"]
	high = high + timings[0]["add"]
	label = timings[0]["label"]
	if label:
		words = words + ", " + label[0].lower() + label[1:]
low = round(low / 10.0) * 10
high = round(high / 10.0) * 10
component.jobs = jobs
component.extras = extras
component.timings = timings
component.ticks = tape_ticks(ticks, cur, tick_label)
component.lo_txt = money(low, cur)
component.hi_txt = money(high, cur)
component.for_txt = words
component.lo = fixed(axis_pos(low, ticks))
component.hi = fixed(axis_pos(high, ticks))
component.component_data = {
	"currency": cur,
	"ticks": ticks,
	"jobs": jobs,
	"extras": extras,
	"timings": timings,
	"others": others,
	"per_job": str(props.get("per_job_note") or ""),
}
